import itertools
def fit_check(blocks):
    # reference = largest-area block
    ref = max(range(len(blocks)), key=lambda i: blocks[i][4].size)
    r0,r1,c0,c1,R = blocks[ref]
    # P: dict (mr,mc)->value from ref, mr=(r-r0)%5 etc
    P={}
    for r in range(R.shape[0]):
        for c in range(R.shape[1]):
            P[((r)%5,(c)%5)]=R[r][c]
    res=[]
    for i,(a0,a1,b0,b1,B) in enumerate(blocks):
        ok_shifts=[]
        for dr in range(5):
            for dc in range(5):
                if all(P.get(((r+dr)%5,(c+dc)%5))==B[r][c] for r in range(B.shape[0]) for c in range(B.shape[1])):
                    ok_shifts.append((dr,dc))
        res.append((i,(a0,b0),B.shape,ok_shifts))
    return ref,res
