def has_sub_wrap(big, small, wrap_rows=True, wrap_cols=True):
    H,W=big.shape; h,w=small.shape
    for r in range(H):
        for c in range(W):
            ok=True
            for dr in range(h):
                for dc in range(w):
                    rr = (r+dr)%H if wrap_rows else r+dr
                    cc = (c+dc)%W if wrap_cols else c+dc
                    if rr>=H or cc>=W or big[rr][cc]!=small[dr][dc]:
                        ok=False; break
                if not ok: break
            if ok: return True
    return False
